    video: { title: 'Ваш ролик, в маленьком круге.', text: 'Выберите видео и фрагмент до 10 секунд. Звук не переносится. Для начала подойдёт 12 кадров в секунду.', formats: 'MP4 / H.264 · WebM / VP8, VP9' },
